 for k in range(4):
  x=np.rot90(m,k)
  for y in [x,np.fliplr(x)]:
   if not any(y.shape==z.shape and np.array_equal(y,z) for z in out):out.append(y.copy())
 return out
def occurrences_union(grid, target, pattern, rots=True, exact=False):
 u=np.zeros_like(grid,dtype=bool); matches=[]
 vv=variants(pattern) if rots else [pattern]
 for m in vv:
  h,w=m.shape
  for r in range(grid.shape[0]-h+1):
   for c in range(grid.shape[1]-w+1):
    patch=grid[r:r+h,c:c+w]
    ok=np.all(patch[m]==0)
    if exact: ok=ok and np.all(patch[~m]!=0)
    if ok:
     u[r:r+h,c:c+w]|=m
     matches.append((r,c,m.shape))
 return u,matches
